                if identifier.isdigit():
                    pre_ids.append((0, int(identifier)))
                else:
                    pre_ids.append((1, identifier))
        else:
            # Version is a normal release (higher precedence than pre-release)
            is_release = 1
            pre_ids = []

        # Return a tuple that respects SemVer precedence rules when compared
        # (major, minor, patch, is_release, pre_release_identifiers)
        return (major, minor, patch, is_release, pre_ids)

    key_a = _parse_version(a)
    key_b = _parse_version(b)

    if key_a < key_b:
        return -1
    elif key_a > key_b:
        return 1
    else:
        return 0

