def parse_csv_line(line: str) -> list[str]:
    fields = []
    current_field = []
    in_quotes = False

    i = 0
    n = len(line)

    while i < n:
        char = line[i]

        if char == '"':
            if in_quotes:
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',':
            if not in_quotes:
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)
        else:
            current_field.append(char)

        i += 1

    fields.append(''.join(current_field))
    return fields

